let conn = Connection::open("audit.sqlite")?;
conn.pragma_update(None, "journal_mode", "WAL")?;   // readers do not block the writer
let (tx, rx) = std::sync::mpsc::channel::<StoredMessage>();
std::thread::spawn(move || {
    let mut ins = conn.prepare("INSERT OR IGNORE INTO msg_store VALUES (?1,?2,?3,?4)")?;
    for m in rx {                                     // single owner: no lock, no sharing
        ins.execute(params![m.id, m.channel, m.ts, serde_json::to_string(&m.body)?])?;
    }
});
// tap side: if tx.send(m).is_err() { drops.inc() }   (never blocks, never panics)

