let pool = SqlitePool::connect("sqlite:audit.db?mode=rwc").await?;
sqlx::query("CREATE TABLE IF NOT EXISTS msg_store"
            "(id TEXT PRIMARY KEY, chan TEXT, ts INTEGER, body TEXT)")
    .execute(&pool).await?;

let (tx, mut rx) = tokio::sync::mpsc::channel::<StoredMessage>(10_000);
tokio::spawn(async move {
    while let Some(m) = rx.recv().await {             // one writer task, serialised writes
        sqlx::query("INSERT OR IGNORE INTO msg_store VALUES (?1,?2,?3,?4)")
            .bind(&m.id).bind(&m.channel).bind(m.ts).bind(&m.body)
            .execute(&pool).await.map(|_| ()).unwrap_or_else(|_| drops.inc());
    }
});
